changeSet.sql:
CREATE TABLE ai_conversation_contract (
    id VARCHAR(36) NOT NULL PRIMARY KEY,
    user_id BIGINT NOT NULL,
    created_at TIMESTAMP NOT NULL,
    active_run_id VARCHAR(36),
    updated_at TIMESTAMP NOT NULL
);
INSERT INTO ai_conversation_contract(id, user_id, created_at, active_run_id, updated_at)
    SELECT id, user_id, created_at, active_run_id, updated_at FROM ai_conversation;
DROP TABLE ai_conversation;
ALTER TABLE ai_conversation_contract RENAME TO ai_conversation;
CREATE INDEX idx_ai_conversation_active_run ON ai_conversation(active_run_id);

CREATE TABLE ai_message_contract (
    message_id VARCHAR(36) NOT NULL PRIMARY KEY,
    conversation_id VARCHAR(36) NOT NULL,
    run_id VARCHAR(36),
    role VARCHAR(16) NOT NULL,
    content TEXT NOT NULL,
    state VARCHAR(24) NOT NULL,
    created_at TIMESTAMP NOT NULL,
    sequence_no BIGINT NOT NULL
);
INSERT INTO ai_message_contract(message_id, conversation_id, run_id, role, content, state, created_at, sequence_no)
    SELECT message_id, conversation_id, run_id, role, content, state, created_at, sequence_no FROM ai_message;
DROP TABLE ai_message;
ALTER TABLE ai_message_contract RENAME TO ai_message;
CREATE INDEX idx_ai_message_conversation ON ai_message(conversation_id, created_at);
